sql_query:
SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Cancer type" = 'Small Cell Lung' AND "Included in MA" = 'Yes' AND "Monotherapy/combination" = 'Combination' AND "Trial phase" = 'Phase 3';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Treatment regimen" AS source_value FROM clinical_trials WHERE "Cancer type" = 'Small Cell Lung' AND "Included in MA" = 'Yes' AND "Monotherapy/combination" = 'Combination' AND "Trial phase" = 'Phase 3'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_added_agents(source_value) AS "added_agents"
FROM base;
